function e($v): string { return htmlspecialchars((string)$v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function dbrows(PDO $db,string $sql,array $args=[]): array { $q=$db->prepare($sql);$q->execute($args);return $q->fetchAll(); }
function dbrow(PDO $db,string $sql,array $args=[]): ?array { return dbrows($db,$sql,$args)[0]??null; }
function jsonval($v): array { if(is_array($v))return $v; if(!$v)return []; return json_decode((string)$v,true)?:[]; }
function urlid($v): string { return rawurlencode((string)$v); }
function pageTitle(string $s): string { return $s.' · Ashwamedh Gurukul'; }
function ico(string $name,int $size=18): string {
 $paths=['book'=>'<path d="M12 7v14"/><path d="M3 18V5a2 2 0 0 1 2-2h4a3 3 0 0 1 3 3 3 3 0 0 1 3-3h4a2 2 0 0 1 2 2v13a1 1 0 0 1-1 1h-5a3 3 0 0 0-3 2 3 3 0 0 0-3-2H4a1 1 0 0 1-1-1Z"/>','home'=>'<path d="m3 10 9-7 9 7"/><path d="M5 9v11h14V9"/><path d="M9 20v-6h6v6"/>','video'=>'<rect x="3" y="5" width="13" height="14" rx="2"/><path d="m16 10 5-3v10l-5-3"/>','award'=>'<circle cx="12" cy="8" r="6"/><path d="M8.2 13.2 7 22l5-3 5 3-1.2-8.8"/>','users'=>'<path d="M16 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="10" cy="7" r="4"/><path d="M20 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>','user'=>'<circle cx="12" cy="8" r="5"/><path d="M20 21a8 8 0 0 0-16 0"/>','search'=>'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>','bell'=>'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/>','menu'=>'<path d="M3 6h18M3 12h18M3 18h18"/>','chev'=>'<path d="m9 18 6-6-6-6"/>','chart'=>'<path d="M3 3v18h18"/><path d="m19 9-5 5-4-4-5 5"/>','globe'=>'<circle cx="12" cy="12" r="10"/><path d="M2 12h20"/><path d="M12 2a15 15 0 0 1 0 20 15 15 0 0 1 0-20"/>','search'=>'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>'];return '<svg aria-hidden="true" width="'.$size.'" height="'.$size.'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'.($paths[$name]??'').'</svg>';
}
function courseCards(array $items): string { if(!$items)return '<div class="empty"><h3>No courses available for this selection</h3><a href="/courses">Browse courses →</a></div>'; $o='<div class="course-grid">';foreach($items as $c){$filters=jsonval($c['filters']??[]);$count=$c['lesson_count']??$c['lessons']??'Explore';$o.='<a class="course-card" href="/course/'.urlid($c['id']).'"><div class="course-card-media" aria-hidden="true"><img src="'.e($c['image']?:'/images/ved.webp').'" alt="" loading="lazy" decoding="async"></div><div><small>'.(!empty($filters['sample'])?'INTRODUCTORY SAMPLE':'ASHWAMEDH LEARNING').'</small><h3>'.e($c['title']).'</h3><p>'.e($c['description']??'').'</p><span>'.ico('book',15).' '.e($count).' lessons</span><strong>View course '.ico('video',14).'</strong></div></a>'; }return $o.'</div>'; }

function rolePortalDashboard(PDO $pdo,array $user,string $role): string {
 $base=match($role){'course_creator'=>'/creator','timetable_manager'=>'/timetable',default=>'/accounts'};
 if($role==='course_creator'){$items=dbrows($pdo,"SELECT status FROM workspace_items WHERE owner_id=? AND kind='course'",[$user['id']]);$metrics=[[count($items),'Courses Created'],[count(array_filter($items,fn($i)=>$i['status']==='submitted')),'Awaiting Approval'],[count(array_filter($items,fn($i)=>$i['status']==='published')),'Published Courses']];$links=[['courses','My Courses'],['course/new','Create Course'],['syllabus','Syllabus Status']];$subtitle='Create and submit course syllabi for review.';}
 elseif($role==='timetable_manager'){$classes=(int)(dbrow($pdo,"SELECT COUNT(*) n FROM workspace_items WHERE kind='live'")['n']??0);$papers=(int)(dbrow($pdo,"SELECT COUNT(*) n FROM workspace_items WHERE kind='exam'")['n']??0);$metrics=[[$classes,'Live Class Entries'],[$papers,'Exam Papers'],[(int)(dbrow($pdo,'SELECT COUNT(*) n FROM courses WHERE published=1')['n']??0),'Published Courses']];$links=[['live-classes','Live Class Schedule'],['exams','Exam Schedule'],['assignments','Assignment Schedule']];$subtitle='Manage academy class and examination schedules.';}
 else{$students=(int)(dbrow($pdo,"SELECT COUNT(*) n FROM users WHERE role='student'")['n']??0);$members=(int)(dbrow($pdo,'SELECT COUNT(*) n FROM memberships')['n']??0);$metrics=[[$students,'Student Accounts'],[$members,'Membership Records'],[(int)(dbrow($pdo,'SELECT COUNT(*) n FROM users')['n']??0),'Total User Accounts']];$links=[['students','Student Accounts'],['memberships','Membership Records'],['payments','Payment Records']];$subtitle='Review student accounts and membership records.';}
 $html='<main class="rp-page"><header class="rp-hero"><div><h1>'.e(match($role){'course_creator'=>'Syllabus / Course Creator Dashboard','timetable_manager'=>'Time Table Manager Dashboard',default=>'Accounts Dashboard'}).'</h1><p>'.e($subtitle).'</p></div></header><div class="rp-page-body"><div class="rp-metrics">';
 foreach($metrics as $i=>$m)$html.='<div class="rp-metric tone-'.($i%6).'"><span>'.ico(['book','award','users'][$i%3],27).'</span><div><strong>'.e($m[0]).'</strong><p>'.e($m[1]).'</p></div></div>';
 $html.='</div><section class="rp-panel"><h2>Quick Actions</h2><div class="rp-department-grid">';
 foreach($links as $i=>$link)$html.='<a class="rp-department tone-'.($i%6).'" href="'.e($base.'/'.$link[0]).'"><strong>'.e($link[1]).'</strong><span>Open →</span></a>';
 return $html.'</div></section></div></main>';
}

function staffDashboard(PDO $pdo,array $user,string $mode): string {
 $items=$mode==='teacher'?dbrows($pdo,'SELECT * FROM workspace_items WHERE owner_id=? ORDER BY updated_at DESC',[$user['id']]):dbrows($pdo,'SELECT * FROM workspace_items ORDER BY updated_at DESC LIMIT 80');
 $pending=count(array_filter($items,fn($i)=>$i['status']==='submitted'));
 if($mode==='admin'){$m=[[(int)(dbrow($pdo,"SELECT COUNT(*) n FROM users WHERE role='student'")['n']??0),'Total Students'],[(int)(dbrow($pdo,"SELECT COUNT(*) n FROM users WHERE role='teacher'")['n']??0),'Total Teachers'],[(int)(dbrow($pdo,'SELECT COUNT(*) n FROM courses')['n']??0),'Total Courses'],[$pending,'Pending Review'],[(int)(dbrow($pdo,'SELECT COUNT(*) n FROM lessons')['n']??0),'Published Lessons'],[(int)(dbrow($pdo,'SELECT COUNT(*) n FROM learning_certificates')['n']??0),'Achievements']];$links=[['students','Student Management'],['teachers','Teacher Management'],['courses','Course & Syllabus'],['approvals','Syllabus Approval'],['content','Content Management'],['results','Reports & Analytics'],['payments','Membership & Access'],['settings','Settings']];$heading='Super Admin Dashboard';$sub='IT Department | Complete academy management';}
 elseif($mode==='reviewer'){$m=[[$pending,'Pending Review'],[count(array_filter($items,fn($i)=>$i['status']==='revision')),'Revision Required'],[count(array_filter($items,fn($i)=>$i['status']==='approved')),'Approved'],[count(array_filter($items,fn($i)=>$i['status']==='published')),'Published']];$links=[['approvals','Review Syllabus'],['submitted','All Submissions'],['messages','Queries & Responses']];$heading='Syllabus Approval Department';$sub='Review + Query + Guide + Approve';}
 else{$courses=array_filter($items,fn($i)=>$i['kind']==='course');$live=array_filter($items,fn($i)=>$i['kind']==='live');$lessons=0;foreach($courses as $c)$lessons+=count(jsonval($c['data'])['modules']??[]);$m=[[count($courses),'Courses Created'],[$lessons,'Lessons Authored'],[count(array_filter($items,fn($i)=>$i['kind']==='exam')),'Exam Papers'],[count(array_filter($courses,fn($i)=>$i['status']==='published')),'Published Courses'],[$pending,'Awaiting Approval'],[count($live),'Live Sessions']];$links=[['course/new','Create New Course'],['lesson','Add New Lesson'],['exam/new','Create Exam Paper'],['ai-exam','Open AI Exam Tools'],['live','Schedule Live Class'],['students','Manage Students'],['results','View Results']];$heading='Welcome '.$user['name'].'!';$sub='Create Knowledge | Build Future | Serve Humanity';}
 $html='<main class="rp-page"><header class="rp-hero"><div><h1>'.e($heading).'</h1><p>'.e($sub).'</p></div><blockquote lang="hi">विद्या ददाति विनयं,<br>विनयाद् याति पात्रताम्।<br><small>ज्ञान · संस्कार · समृद्धि</small></blockquote></header><div class="rp-page-body"><div class="rp-metrics">';
 foreach($m as $i=>$metric)$html.='<div class="rp-metric tone-'.($i%6).'"><span>'.ico(['book','book','award','users','chart','award'][$i%6],29).'</span><div><strong>'.e($metric[0]).'</strong><p>'.e($metric[1]).'</p></div></div>';
 $html.='</div>';if($mode==='admin'){$html.='<div class="rp-department-grid">';foreach($links as $i=>$link)$html.='<a class="rp-department tone-'.($i%6).'" href="/super-admin/'.e($link[0]).'">'.ico('book',24).'<strong>'.e($link[1]).'</strong><span>View →</span></a>';$html.='</div>';}
 $html.='<div class="rp-dashboard-grid"><section class="rp-panel rp-main-panel"><div class="rp-panel-title"><h2>'.($mode==='reviewer'?'Approval Queue':($mode==='admin'?'Recent Course Drafts':'My Courses')).'</h2><a class="button small" href="'.($mode==='reviewer'?'/review/approvals':($mode==='admin'?'/super-admin/courses':'/teacher/courses')).'">View all →</a></div>';
 $visible=array_values(array_filter($items,fn($i)=>$mode==='reviewer'?$i['status']==='submitted':$i['kind']==='course'));foreach(array_slice($visible,0,5) as $i)$html.='<article class="rp-course-row"><img src="'.e(jsonval($i['data'])['image']??'/images/ved.webp').'" alt=""><div><h3>'.e($i['title']).'</h3><p>'.e($i['kind']).' · '.e($i['status']).'</p></div><span class="rp-status '.e($i['status']).'">'.e($i['status']).'</span><a class="button outline small" href="'.($mode==='reviewer'?'/review/approvals?item='.urlid($i['id']):'/teacher/course/'.urlid($i['id'])).'">'.($mode==='reviewer'?'Review':'Open').'</a></article>';
 if(!$visible)$html.='<div class="rp-empty"><h3>'.($mode==='reviewer'?'No pending submissions':'Your teaching journey begins here').'</h3><p>'.($mode==='reviewer'?'Submitted work will appear for review.':'Create your first course, add lessons, and send it for review.').'</p></div>';
 $html.='</section><section class="rp-panel"><div class="rp-panel-title"><h2>Quick Actions</h2></div>';foreach($links as $link)$html.='<a class="rp-action" href="'.($mode==='reviewer'?'/review':'/'.($mode==='admin'?'super-admin':'teacher')).'/'.e($link[0]).'">'.ico('book',18).e($link[1]).'<span>→</span></a>';$html.='</section></div></div></main>';return $html;
}
function publishWorkspaceCourse(PDO $pdo,array $item): void {
 $data=jsonval($item['data']);$category=$data['category_id']??'gurukul-0';$categoryExists=dbrow($pdo,'SELECT id FROM categories WHERE id=?',[$category]);if(!$categoryExists)$category='gurukul-0';
 $pdo->prepare('INSERT INTO courses(id,category_id,title,description,image,instructor,filters,published,featured) VALUES(?,?,?,?,?,?,?,1,0) ON DUPLICATE KEY UPDATE title=VALUES(title),description=VALUES(description),published=1')->execute([$item['id'],$category,$item['title'],$data['description']??'',$data['image']??'/images/course-vedic-study.png',$data['instructor']??$item['owner_name']??'Ashwamedh Gurukul',json_encode($data['filters']??[],JSON_UNESCAPED_UNICODE)]);
  foreach (($data['modules'] ?? []) as $mi => $module) {
   $chapterId = $item['id'] . '--module-' . $mi;
   $pdo->prepare('INSERT IGNORE INTO chapters(id,course_id,title,position) VALUES(?,?,?,?)')->execute([$chapterId,$item['id'],$module['title'] ?? ('Module ' . ($mi+1)),$mi]);
   foreach (($module['lessons'] ?? []) as $li => $lesson) {
    $lessonId = $item['id'] . '--lesson-' . $mi . '-' . $li;
    $pdo->prepare('INSERT IGNORE INTO lessons(id,chapter_id,title,body,hindi,english,video_url,pdf_url,ppt_url,source_url,duration,position,is_free) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$lessonId,$chapterId,$lesson['title'] ?? 'Lesson',$lesson['body'] ?? '',$lesson['hindi'] ?? '',$lesson['english'] ?? '',$lesson['video_url'] ?? '',$lesson['pdf_url'] ?? '',$lesson['ppt_url'] ?? '',$lesson['source_url'] ?? '',(int)($lesson['duration'] ?? 0),$li,!empty($lesson['is_free'])]);
    foreach (($lesson['questions'] ?? []) as $question) { $options=$question['options'] ?? []; if (is_array($options)) $options=json_encode($options,JSON_UNESCAPED_UNICODE); $pdo->prepare('INSERT INTO questions(lesson_id,prompt,options,answer,explanation) VALUES(?,?,?,?,?)')->execute([$lessonId,$question['prompt'] ?? '',$options,(int)($question['answer'] ?? 0),$question['explanation'] ?? '']); }
   }
  }
}
