function csrfField(): string { return '<input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'">'; }
function escapeJson($v): string { return e(json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)); }
function doPost(PDO $pdo,?array $user): void {
 if($_SERVER['REQUEST_METHOD']!=='POST')return; csrf_check();$action=$_POST['action']??'';
 if($action==='login'){$email=strtolower(trim($_POST['email']??''));$q=$pdo->prepare('SELECT * FROM users WHERE email=?');$q->execute([$email]);$u=$q->fetch();$portal=$_POST['portal']??'student';$loginPaths=['student'=>'/login','teacher'=>'/teacher/login','course_creator'=>'/creator/login','reviewer'=>'/review/login','timetable_manager'=>'/timetable/login','accounts'=>'/accounts/login','admin'=>'/super-admin/login'];$allow=['student'=>'student','teacher'=>'teacher','course_creator'=>'course_creator','reviewer'=>'reviewer','timetable_manager'=>'timetable_manager','accounts'=>'accounts','admin'=>'admin'];if(!$u||!password_verify($_POST['password']??'',$u['password_hash'])){$_SESSION['flash']='Email or password is incorrect.';go($loginPaths[$portal]??'/login');}if(($allow[$portal]??null)!==$u['role']){$_SESSION['flash']='This account cannot sign in to this portal. Use your assigned academy login URL.';go($loginPaths[$portal]??'/login');}session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role'],'photo'=>$u['photo']??''];go(match($u['role']){'admin'=>'/super-admin','teacher'=>'/teacher','course_creator'=>'/creator','reviewer'=>'/review','timetable_manager'=>'/timetable','accounts'=>'/accounts',default=>'/dashboard'});}
  if($action==='register'){$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$confirmEmail=strtolower(trim($_POST['confirmEmail']??''));$password=$_POST['password']??'';$dateOfBirth=trim($_POST['dateOfBirth']??'');$required=['phone','state','district','village','postalCode','gurukulBranch'];$missing=false;foreach($required as $field){if(trim($_POST[$field]??'')===''){$missing=true;break;}}$date=DateTime::createFromFormat('!Y-m-d',$dateOfBirth);$validDate=$dateOfBirth!==''&&$date!==false&&$date->format('Y-m-d')===$dateOfBirth&&$dateOfBirth<=date('Y-m-d');$country=trim($_POST['country']??'India');$stateValue=trim($_POST['state']??'');$stateOk=$country==='India'?in_array($stateValue,india_states(),true):($stateValue!==''&&mb_strlen($stateValue)<=100);if(!$stateOk)$missing=true;if(mb_strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||$email!==$confirmEmail||$missing||!$validDate||strlen($password)<12||$password!==($_POST['confirmPassword']??'')){$_SESSION['flash']='Check your details. Emails and passwords must match, all required student details must be filled, and passwords need at least 12 characters.';go('/signup');}$q=$pdo->prepare('INSERT INTO users(email,name,password_hash,phone,education,date_of_birth,country,state,district,tehsil,village,postal_code,gurukul_branch) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');try{$q->execute([$email,$name,password_hash($password,PASSWORD_DEFAULT),trim($_POST['phone']??''),trim($_POST['education']??''),$dateOfBirth,trim($_POST['country']??'India'),trim($_POST['state']??''),trim($_POST['district']??''),trim($_POST['tehsil']??''),trim($_POST['village']??''),trim($_POST['postalCode']??''),trim($_POST['gurukulBranch']??'')]);$_SESSION['user']=['id'=>(int)$pdo->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'student'];go('/dashboard');}catch(PDOException $ex){error_log('Student registration database error ['.$ex->getCode().']: '.$ex->getMessage());if((int)($ex->errorInfo[1]??0)===1062){$_SESSION['flash']='Email already registered. Please sign in.';go('/signup');}$_SESSION['flash']='Your account could not be saved. Please try again or contact the academy administrator.';go('/signup');}}
  if($action==='creator_register'){$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$confirmEmail=strtolower(trim($_POST['confirmEmail']??''));$password=$_POST['password']??'';if(mb_strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||$email!==$confirmEmail||strlen($password)<12||$password!==($_POST['confirmPassword']??'')){$_SESSION['flash']='Check your details. Emails and passwords must match, and passwords need at least 12 characters.';go('/creator/signup');}try{$q=$pdo->prepare("INSERT INTO users(email,name,password_hash,phone,role) VALUES(?,?,?,?, 'course_creator')");$q->execute([$email,$name,password_hash($password,PASSWORD_DEFAULT),trim($_POST['phone']??'')]);$id=(int)$pdo->lastInsertId();session_regenerate_id(true);$_SESSION['user']=['id'=>$id,'name'=>$name,'email'=>$email,'role'=>'course_creator'];go('/creator');}catch(PDOException $ex){error_log('Course creator registration database error ['.$ex->getCode().']: '.$ex->getMessage());$_SESSION['flash']=(int)($ex->errorInfo[1]??0)===1062?'Email already registered. Please sign in.':'Your account could not be saved. Please try again or contact the academy administrator.';go('/creator/signup');}}
 if($action==='logout'){$_SESSION=[];session_regenerate_id(true);go('/');}
 if($action==='bookmark'){$u=$user??require_user();$id=$_POST['course_id']??'';$pdo->prepare('INSERT IGNORE INTO bookmarks(user_id,course_id) VALUES(?,?)')->execute([$u['id'],$id]);$_SESSION['flash']='Course added to your learning.';go('/course/'.urlid($id));}
 if($action==='unbookmark'){$u=require_user();$pdo->prepare('DELETE FROM bookmarks WHERE user_id=? AND course_id=?')->execute([$u['id'],$_POST['course_id']??'']);go('/bookmarks');}
 if($action==='progress'){$u=require_user();$pdo->prepare('INSERT INTO progress(user_id,lesson_id,completed) VALUES(?,?,1) ON DUPLICATE KEY UPDATE completed=1')->execute([$u['id'],$_POST['lesson_id']??'']);$_SESSION['flash']='Lesson completed.';go('/dashboard');}
 if($action==='quiz'){$u=require_user();$id=$_POST['lesson_id']??'';$qs=dbrows($pdo,'SELECT * FROM questions WHERE lesson_id=? ORDER BY id',[$id]);$answers=$_POST['answer']??[];$score=0;foreach($qs as $q)if((int)($answers[$q['id']]??-1)===(int)$q['answer'])$score++;if($qs){$pdo->prepare('INSERT INTO quiz_attempts(user_id,lesson_id,score,total) VALUES(?,?,?,?)')->execute([$u['id'],$id,$score,count($qs)]);$_SESSION['flash']="Your score: $score / ".count($qs);}$pdo->prepare('INSERT INTO progress(user_id,lesson_id,completed) VALUES(?,?,1) ON DUPLICATE KEY UPDATE completed=1')->execute([$u['id'],$id]);go('/lesson/'.urlid($id));}
 if($action==='profile'){$u=require_user();$pdo->prepare('UPDATE users SET name=?,phone=?,education=?,date_of_birth=?,country=?,state=?,district=?,tehsil=?,village=?,postal_code=?,gurukul_branch=? WHERE id=?')->execute([trim($_POST['name']??$u['name']),trim($_POST['phone']??''),trim($_POST['education']??''),$_POST['dateOfBirth']?:null,$_POST['country']??'',$_POST['state']??'',$_POST['district']??'',$_POST['tehsil']??'',$_POST['village']??'',$_POST['postalCode']??'',$_POST['gurukulBranch']??'',$u['id']]);$_SESSION['user']['name']=trim($_POST['name']??$u['name']);$_SESSION['flash']='Profile updated.';go('/profile');}
 if($action==='new_workspace'){$u=require_role(['teacher','course_creator','admin']);$id='work-'.bin2hex(random_bytes(8));$title=trim($_POST['title']??'');$kind=$_POST['kind']??'course';if($title){$pdo->prepare('INSERT INTO workspace_items(id,owner_id,kind,title,data,status) VALUES(?,?,?,?,?,?)')->execute([$id,$u['id'],$kind,$title,json_encode($_POST['data']??[],JSON_UNESCAPED_UNICODE),'submitted']);$_SESSION['flash']='Submitted for review.';}go($u['role']==='course_creator'?'/creator/courses':'/teacher/courses');}
 if($action==='review'){$u=require_role(['reviewer','admin']);$status=$_POST['status']??'revision';if(in_array($status,['revision','approved','published'],true)){$item=dbrow($pdo,'SELECT w.*,u.name owner_name FROM workspace_items w JOIN users u ON u.id=w.owner_id WHERE w.id=?',[$_POST['item_id']??'']);if($item){if($status==='published'&&$item['kind']==='course')publishWorkspaceCourse($pdo,$item);$pdo->prepare('UPDATE workspace_items SET status=? WHERE id=?')->execute([$status,$item['id']]);}}go($u['role']==='admin'?'/super-admin/approvals':'/review/approvals');}
