ults</h1><p>Review your quiz results and progress.</p></div></header><div class="rp-panel">';foreach($rows as $r)$content.='<div class="rp-row"><span><b>'.e($r['course_title']).'</b><small>'.e($r['lesson_title']).'</small></span><strong>'.e($r['score']).' / '.e($r['total']).'</strong></div>';if(!$rows)$content.='<p>Complete a chapter quiz to see your results.</p>';$content.='</div>';}else{$content.='<header class="rp-hero"><div><h1>'.e($title).'</h1><p>Explore your learning achievements and upcoming activities.</p></div></header><section class="rp-panel"><p>There are no items to show yet.</p><a href="/courses">Explore courses →</a></section>';}$content.='</main>';}
