 elseif($mode==='admin'&&$slug==='content'){$entity=$_GET['entity']??'courses';$allowed=['categories','courses','chapters','lessons'];$entity=in_array($entity,$allowed,true)?$entity:'courses';$rows=dbrows($pdo,"SELECT * FROM `$entity` ORDER BY id LIMIT 100");$content.='<section class="rp-panel"><h2>Manage Your Academy</h2><p>Add content through records: create a category, course, chapter, then lesson.</p><form method="get" class="admin-select"><input type="hidden" name="view" value="content"><label>Content type<select name="entity" onchange="this.form.submit()">';foreach($allowed as $e1)$content.='<option'.($entity===$e1?' selected':'').'>'.e($e1).'</option>';$content.='</select></label></form><div class="admin-layout"><aside class="admin-records">';foreach($rows as $r)$content.='<div class="record"><b>'.e($r['title']??$r['id']).'</b><small>'.e($r['id']).'</small></div>';$content.='</aside><form method="post" class="admin-form">'.csrfField().'<input type="hidden" name="action" value="admin_content"><input type="hidden" name="entity" value="'.e($entity).'">';$fields=['categories'=>['id','title','system','image','position'],'courses'=>['id','category_id','title','description','image','instructor','published','featured'],'chapters'=>['id','course_id','title','position'],'lessons'=>['id','chapter_id','title','body','hindi','english','video_url','pdf_url','ppt_url','source_url','duration','position','is_free']];foreach($fields[$entity] as $f)$content.='<label>'.e(ucwords(str_replace('_',' ',$f))).'<input name="'.e($f).'" '.(in_array($f,['description','body','hindi','english'],true)?'':'required').'></label>';$content.='<button class="button">Save record</button></form></div></section>';}
